from copy import deepcopy
from prepare_audit import OUT,read,save,sha

TRIAL=OUT/'process_relation_trial_014'
EXTENSION='process_saved_electronic_film_branches_recovery'


def build(r,a):
 f=r['fragments'];v=lambda g,k:f[g]['captures'][k]['value_raw'];materials=[];states=[];ops=[];orders=[];bindings=[]
 def par(role,g,k):return dict(role=role,value_raw=v(g,k),unit_raw=None,source_fragment=g,source_capture=k)
 def op(ident,label,name,ins,outs,params,product,purpose):
  ops.append(dict(id=ident,kind='operation',sample=label,name=name,inputs=ins,outputs=outs,parameters=params,purpose=purpose));bindings.append(dict(id='SCOPE_'+ident,kind='binding',sample=label,operation_id=ident,input_nodes=ins,output_states=outs,purpose=purpose,existing_material_identity_target=product['material_target'],physical_identity_with_other_test_specimens_not_asserted=True))
 for i,p in enumerate(r['products']):
  label='polymer '+p['number'];pre='P'+p['number'];material=pre+'_DCE_FRACTION';materials.append(dict(id=material,kind='material_identity_annotation',sample=label,fraction='DCE fraction',existing_material_target=p['fraction_target'],physical_form_and_unrecovered_dissolution_not_asserted=True))
  for method in ['CAST','SPIN']:
   ident=pre+'_SEM_'+method;node=ident+'_FILM';surface=v('body','cast_surface') if method=='CAST' else v('body','spin_surface')+'; '+v('body','spin_comparison');states.append(dict(id=node,kind='state',sample=label,state='film on the reported ITO glass substrate',surface_description=surface,preparation_method=v('sem_method','cast' if method=='CAST' else 'spin'),purpose='SEM',physical_identity_with_UPS_or_conductivity_films_not_asserted=True));op(ident,label,v('sem_method','cast' if method=='CAST' else 'spin'),[material],[node],[par('substrate','sem_method','substrate')],p,'SEM')
  ups=pre+'_UPS_PREPARE';upstate=pre+'_UPS_FILM';reports=[dict(report_origin='experimental sentence',wording=v('ups_method','deposition_description'),source_fragment='ups_method',scope='reported two-formula cohort; not imposed as one unique mode'),dict(report_origin='results tied to Figures '+v('ups_results','figure_a')+'/'+v('ups_results','figure_b'),wording=v('ups_results','method'),source_fragment='ups_results',scope='reported for both numbered polymers')];states.append(dict(id=upstate,kind='state',sample=label,state='thin film on gold-coated glass for UPS',preparation_temperature=v('ups_method','temperature'),preparation_atmosphere=v('ups_method','atmosphere'),deposition_reports=reports,unique_deposition_mode_not_asserted=True));op(ups,label,'prepare film for UPS',[material],[upstate],[par('substrate','ups_method','substrate'),par('preparation temperature','ups_method','temperature'),par('preparation atmosphere','ups_method','atmosphere'),dict(role='source-local deposition descriptions',reported_descriptions=reports,one_mode_not_forced=True)],p,'UPS')
  neutral=pre+'_CONDUCTIVITY_UNDOPED';doped=pre+'_CONDUCTIVITY_DOPED';air=pre+'_CONDUCTIVITY_AFTER_AIR';states += [dict(id=neutral,kind='state',sample=label,state=v('body','state')+' film in conductivity study',initial_color_and_substrate_not_recovered=True),dict(id=doped,kind='state',sample=label,state='iodine-doped film',color=v('body','output_color'),temperature=v('doping_temperature','temperature'),desiccator_and_light_condition_not_recovered=True),dict(id=air,kind='state',sample=label,state='air-exposed iodine-doped conductivity film',observation=v('body','conductivity_change'),exact_conductivity_not_reextracted=True)]
  interval=dict(role='initial conductivity-evolution observation interval, not total treatment duration',value_raw=v('body','window_duration'),unit_raw=v('body','window_duration_unit'),qualifier_raw=v('body','window_qualifier'),source_fragment='body',source_captures=['window_qualifier','window_duration','window_duration_unit'],not_an_imposed_reaction_hold=True)
  op(pre+'_DOPE',label,'dope conductivity film with iodine',[neutral],[doped],[par('dopant','body','dopant'),par('doping temperature','doping_temperature','temperature'),interval],p,'conductivity doping')
  op(pre+'_EXPOSE_AIR',label,v('body','air_action'),[doped],[air],[par('exposure medium','body','air_medium'),dict(role='post-doping air exposure duration',value_raw=v('body','air_duration'),unit_raw=v('body','air_duration_unit'),source_fragment='body',source_captures=['air_duration','air_duration_unit'])],p,'post-doping conductivity observation');orders.append(dict(id=pre+'_DOPING_BEFORE_AIR',kind='order',before=pre+'_DOPE',after=pre+'_EXPOSE_AIR',relation='precedes',basis='the source explicitly exposes already-doped films to air and then reports 24h change'))
 if r['existing_unqualified_doping_interval_points']:bindings.append(dict(id='OLD_DOPING_INTERVAL_ROLE_CLARIFICATION',kind='binding',existing_property_point_targets=r['existing_unqualified_doping_interval_points'],applies_to_operations=['P'+p['number']+'_DOPE' for p in r['products']],correct_role='first conductivity-evolution observation interval, not an imposed total doping duration',original_property_point_or_consumer_bindings_modified=False))
 return dict(proposal_id=r['proposal_id'],materials=materials,operations=ops,parameters=[],states=states,orders=orders,bindings=bindings,saved_fragments=f,source_approval_path=a['path'],source_approval_sha256=a['sha256'],SEM_UPS_and_conductivity_specimens_not_physically_equated=True,initial_color_assignment_to_individual_polymers_not_recovered=True,desiccator_light_condition_and_powder_dopant_form_not_recovered=True,dichloromethane_solution_and_dipping_not_recovered=True,new_property_values_or_original_consumer_bindings_added=0,new_pdf_information_extracted=0)


def main():
 pp=OUT/'process_relation_trial_013/freeze.json';parent=read(pp);approved={x['reference_no']:x for x in read(OUT/'saved_electronic_film_branches_recovery/source_reviews/manifest.json')['papers']};rows=[]
 for p in parent['papers']:
  assert sha(p['candidate_path'])==p['candidate_sha256'];row=deepcopy(p);row['changed_from_immediate_parent']=False
  if p['reference_no'] in approved:
   a=approved[p['reference_no']];assert sha(a['path'])==a['sha256'];ap=read(a['path']);assert sha(ap['proposal_path'])==ap['proposal_sha256'];r=read(ap['proposal_path'])['proposals'][0];old=read(p['candidate_path']);new=deepcopy(old);new[EXTENSION]=[build(r,a)];dest=TRIAL/'papers'/(p['reference_no']+'.json');save(dest,new);row.update(candidate_path=str(dest),candidate_sha256=sha(dest),changed_from_parent=True,changed_from_immediate_parent=True,immediate_parent_candidate_path=p['candidate_path'],immediate_parent_candidate_sha256=p['candidate_sha256'])
  rows.append(row)
 save(TRIAL/'freeze.json',dict(version='process_relation_trial_014',parent_trial='process_relation_trial_013',parent_trial_freeze_sha256=sha(pp),baseline_candidate='candidate_v10',baseline_candidate_freeze_sha256=sha(OUT/'candidate_v10/freeze.json'),prediction_application_code_sha256=sha(__file__),proposal_generation_code_sha256=sha(OUT/'propose_saved_electronic_film_branches.py'),papers=rows,papers_total=101,cumulative_changed_papers=sum(bool(p.get('changed_from_parent')) for p in rows),changed_papers_this_round=1,property_content_or_bindings_modified=False,frozen_original_outputs_modified=False,existing_process_fields_revised=0,reference_answers_or_scores_used_as_prediction_inputs=False,reference_seen_previously_during_error_diagnosis=True,new_pdf_information_extracted=0,stable_workflow_release=False,external_api_calls=0));print({'papers':101,'changed_this_round':1,'cumulative_changed_papers':sum(bool(p.get('changed_from_parent')) for p in rows)})

if __name__=='__main__':main()
